public class Oficina {

    // Atributos
    private String codigo;
    private String inquilino;
    private double consumoValle;
    private double consumoNormal;
    private double consumoPunta;
    private double creditos;

    public Oficina() {
        codigo = "";
        inquilino = "";
        consumoValle = 0;
        consumoNormal = 0;
        consumoPunta = 0;
        creditos = 0;
    }


    // Constructor con atributos default
    public Oficina(String codigo, String inquilino) {
        this.codigo = codigo;
        this.inquilino = inquilino;
        consumoValle = 0;
        consumoNormal = 0;
        consumoPunta = 0;
        creditos = 0;
    }


    // Getters. Solo getters, los "setters" serán cubiertos en otros métodos más adelatne

    public String getCodigo() {
        return codigo;
    }

    public String getInquilino() {
        return inquilino;
    }

    public double getConsumoValle() {
        return consumoValle;
    }

    public double getConsumoNormal() {
        return consumoNormal;
    }

    public double getConsumoPunta() {
        return consumoPunta;
    }

    public double getCreditos() {
        return creditos;
    }


    // Registrar consumo de la oficina

    public void registrarConsumo(double consumo, int horaDia) {

        // Si el consumo no es valido, no se registra (mismo método que EasySpacey, no nan no Infinito)
        if (consumo < 0 || Double.isNaN(consumo) || Double.isInfinite(consumo)) {
            return;
        }

        // Valida la hora en mod24
        if (horaDia < 0 || horaDia > 23) {
            return;
        }

        // Determina si es de la hora valle
        if (horaDia >= 22 || horaDia < 6) {
            consumoValle += consumo;
        }

        // Si es del horario normal
        else if (horaDia < 18) {
            consumoNormal += consumo;
        }

        // Y si no era nada de lo anterior, es hora pico (punta)
        else {
            consumoPunta += consumo;
        }
    }


    // Agregar cre´ditos de una Alerta

    public void agregarCredito(double monto) {

        // Solo se aceptan montos validos
        if (monto <= 0 || Double.isNaN(monto) || Double.isInfinite(monto)) {
            return;
        }

        creditos += monto; 
		//Es la la Alerta la que los calculará. Este solo recibe el monto
    }


    // Reset de acumulados (hora 24 del día)

    public void reiniciarAcumulados() {
        consumoValle = 0;
        consumoNormal = 0;
        consumoPunta = 0;
        creditos = 0;
    }


    // toString para que muestre los datos

    @Override
    public String toString() {
        return "Codigo: " + codigo
                + "\nInquilino: " + inquilino
                + "\nConsumo Valle: " + consumoValle + " kWh"
                + "\nConsumo Normal: " + consumoNormal + " kWh"
                + "\nConsumo Punta: " + consumoPunta + " kWh"
                + "\nCreditos: Q" + String.format("%.2f", creditos);
    }
}
